/* 1.161.19: the logo has width/height attributes, but the header CSS sets both to auto,
 * so Lighthouse flags it as unsized. aspect-ratio keeps its box reserved. All pages. */
add_action( 'wp_head', function () {
	echo '<style id="nura-r19-logo">img.custom-logo{aspect-ratio:320/138}</style>' . "\n";
}, 2 );
